// for await over JavaScript array literals that mix promises and plain
// values: each value is awaited, as the async-from-sync iterator does.
'use strict';
async function run() {
  var out = [];
  for await (var p of [Promise.resolve('p1'), 'p2', Promise.resolve(3)]) out.push(typeof p + ':' + p);
  for await (let q of [1, Promise.resolve({ n: 2 }), null]) out.push(JSON.stringify(q));
  for await (const r of ['a', Promise.resolve('b'), 'c']) {
    if (r === 'b') break;
    out.push('r:' + r);
  }
  try {
    for await (const s of ['ok', Promise.reject(new Error('rejected element')), 'never']) out.push('s:' + s);
  } catch (error) {
    out.push(error.message);
  }
  return out;
}
module.exports = { run };
